import subprocess, json, sys
def backup_incremental(source: str, destination: str): # Executa rsync com flags --delete e -avzn para simular incremental seguro.
    cmd = ['rsync', '-avnz', '--link-dest=' + '/tmp/last_backup_state/' if os.path.exists('/tmp/last_backup_state/') else '', source + '/', destination]
    result = subprocess.run(cmd, capture_output=True, text=True)
    return {'status': 'success' if result.returncode == 0 else 'failed', 'output': result.stdout}

