class port_scanner_lite:
    name = "port_scanner_lite"
    description = "Varre portas específicas em um host para verificar se estão abertas."
    input_schema = {
        "type": "object",
        "properties": {
            "host": {"type": "string", "description": "Endereço IP ou hostname do alvo."},
            "ports": {"type": "array", "items": {"type": "integer"}, "description": "Lista de portas para verificar."}
        },
        "required": ["host", "ports"]
    }
    when_to_use = "Quando o usuário precisar verificar a acessibilidade de serviços em uma lista específica de portas."
    when_not_to_use = "Para varreduras completas de 0-65535 ou ataques ativos; use apenas para verificações pontuais autorizadas."

    def execute(self, **kwargs) -> str:
        host = kwargs.get("host")
        ports = kwargs.get("ports", [])
        results = []
        for port in ports:
            try:
                sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                sock.settimeout(2)
                result = sock.connect_ex((host, port))
                status = "ABERTA" if result == 0 else "FECHADA/BLOQUEADA"
                results.append(f"Porta {port}: {status}")
                sock.close()
            except Exception as e:
                results.append(f"Porta {port}: ERRO ({e})")
        return "\n".join(results)

