import json
from typing import List, Dict, Any

class ToolSpec:
    name = "csv_merger"
    description = "Mescla múltiplos arquivos CSV baseados em uma coluna de chave comum (ex: id_produto). Retorna o resultado como JSON."
    input_schema = {
        "type": "object",
        "properties": {
            "file_paths": {
                "type": "array", 
                "items": {"type": "string"},
                "description": "Lista de caminhos para os arquivos CSV."
            },
            "key_column": {
                "type": "string",
                "description": "Nome da coluna chave comum a todos os arquivos (padrão: 'id')."
            }
        },
        "required": ["file_paths", "key_column"]
    }
    when_to_use = "Quando o usuário precisa unir dados de vários CSVs que possuem colunas distintas mas uma coluna ID compartilhada."
    when_not_to_use = "Não use se os arquivos não tiverem a chave comum ou se forem formatos binários."

    def execute(self, **kwargs) -> str:
        import csv

        file_paths = kwargs.get("file_paths", [])
        key_column = kwargs.get("key_column")

        if not file_paths or len(file_paths) < 2:
            return json.dumps({"error": "São necessários pelo menos dois arquivos CSV para mesclar."}, ensure_ascii=False)

        merged_data = {}
        processed_files_count = 0

        for path in file_paths:
            try:
                with open(path, mode='r', encoding='utf-8') as f:
                    reader = csv.DictReader(f)
                    headers = reader.fieldnames

                    if key_column not in headers:
                        continue # Pula arquivos sem a chave especificada (opcional: poderia lançar erro)

                    for row in reader:
                        key_value = str(row.get(key_column))
                        if key_value:
                            if key_value not in merged_data:
                                merged_data[key_value] = {}
                            # Adiciona colunas do arquivo atual ao registro, prefixando para evitar conflitos se nomes forem iguais
                            for k, v in row.items():
                                if k != key_column:
                                    source_file_name = path.split('/')[-1].replace('.csv', '')
                                    merged_data[key_value][f"{source_file_name}_{k}"] = v
                processed_files_count += 1
            except FileNotFoundError:
                continue # Ignora arquivos inexistentes na lógica de mesclagem

        if not merged_data:
             return json.dumps({"error": "Nenhum dado válido encontrado com a chave especificada."}, ensure_ascii=False)

        result = [
            {key_column: k, **values}
            for k, values in sorted(merged_data.items())
        ]

        return json.dumps(result, indent=2, ensure_ascii=False)

