import socket
from typing import Dict, Any

class port_scanner_lite:
    name = "port_scanner_lite"
    description = "Escaneia um host para verificar portas TCP abertas em uma faixa específica."
    input_schema = {
        "type": "object",
        "properties": {
            "host": {"type": "string", "description": "O endereço IP ou hostname a ser verificado."},
            "start_port": {"type": "integer", "description": "A porta inicial da faixa."},
            "end_port": {"type": "integer", "description": "A porta final da faixa (inclusiva)."}
        },
        "required": ["host", "start_port", "end_port"]
    }
    when_to_use = "Quando o usuário precisa verificar a disponibilidade de portas TCP em um host remoto ou local."
    when_not_to_use = "Não use para escaneamento massivo não autorizado; limite faixas pequenas para testes rápidos."

    def execute(self, **kwargs) -> str:
        host = kwargs.get("host")
        start_port = int(kwargs.get("start_port"))
        end_port = int(kwargs.get("end_port"))
        open_ports = []

        for port in range(start_port, end_port + 1):
            try:
                sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                result = sock.connect_ex((host, port))
                if result == 0:
                    open_ports.append(port)
                sock.close()
            except Exception as e:
                continue

        if not open_ports:
            return f"Nenhuma porta aberta encontrada em {host} entre a faixa de portas solicitada."
        else:
            ports_str = ", ".join(map(str, open_ports))
            return f"Portas abertas detectadas em {host}: [{ports_str}]"

#!/usr/bin/env python3
"""
Tool: json_flattener
Funcao: Achata dicionarios aninhados para estrutura plana (estilo CSV).
"""
import json
from typing import Dict, Any, List

class ToolSpec:
    name = "json_flattener"
    description = "Achata um objeto JSON aninhado em um dicionario de chave unica separado por ponto para planilhas."
    input_schema = {
        "type": "object",
        "properties": {
            "data_json_string": {
                "type": "string",
                "description": "String contendo o JSON a ser achatado."
            }
        },
        "required": ["data_json_string"]
    }
    when_to_use = "Quando necessario converter dados hierarquicos em linhas planas para CSV ou banco de relacional."
    when_not_to_use = "Quando a estrutura aninhada precisa ser preservada ou para arquivos XML/HTML."

    def execute(self, **kwargs) -> str:
        try:
            data_str = kwargs.get("data_json_string")
            if not isinstance(data_str, str):
                return json.dumps({"error": "Entrada deve ser uma string JSON."}, ensure_ascii=False)

            # Parse do input
            data_obj = json.loads(data_str)
            flattened = {}
            self._flatten_dict(data_obj, flattened, prefix="")

            return json.dumps(flattened, indent=2, ensure_ascii=False)
        except Exception as e:
            return json.dumps({"error": f"Falha ao processar JSON: {str(e)}"}, ensure_ascii=False)

    def _flatten_dict(self, d: Dict[str, Any], out: Dict[str, str], parent_key: str = "", sep: str = "."):
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                self._flatten_dict(v, out, new_key, sep=sep)
            elif isinstance(v, list) and len(v) == 1:
                 # Caso opcional: lista com unico item vira valor direto ou array string?
                 # Para CSV simples, convertemos lista para string separada por virgula
                out[new_key] = json.dumps(v)
            else:
                try:
                    out[new_key] = str(v) if not isinstance(v, (str, int, float)) and v is not None else v
                except TypeError:
                    out[new_key] = "" 
        return out

def main():
    # Teste rapido se executado diretamente
    test_input = '{"id": 101, "vendedor": "Ana", "cliente": {"nome": "Carlos Lima", "endereco": {"cidade": "Sao Paulo", "cep": "01310-200"}}, "total": 540.50}'
    tool = ToolSpec()
    print(tool.execute(data_json_string=test_input))

if __name__ == "__main__":
    main()

