import markdown
from typing import Dict, Any

class ToolSpec:
    name: str = "markdown_to_html"
    description: str = "Converte texto Markdown em HTML com estilos CSS personalizados embutidos."
    input_schema: Dict[str, Any] = {
        "type": "object",
        "properties": {
            "content_md": {"type": "string", "description": "O conteúdo bruto no formato Markdown."},
            "title_color": {"type": "string", "default": "#1a5276", "description": "Cor hexadecimal para títulos (ex: #003399)."}
        },
        "required": ["content_md"]
    }
    when_to_use: str = "Quando o usuário solicitar conversão de Markdown para HTML com formatação visual específica."
    when_not_to_use: str = "Não usar se a tarefa for apenas processamento de texto plano ou análise sem necessidade de renderização web."

    def execute(self, **kwargs) -> str:
        content_md = kwargs.get("content_md")
        title_color = kwargs.get("title_color", "#1a5276")

        if not content_md:
            return "Erro: O conteúdo Markdown não pode estar vazio."

        extensions = ['tables', 'fenced_code']
        raw_html = markdown.markdown(content_md, extensions=extensions)

        css_styles = f"""
        <style>
          body {{ font-family: Arial, sans-serif; color: #333; line-height: 1.6; }}
          h1, h2, h3, h4, h5, h6 {{ color: {title_color}; border-bottom: 1px solid #eee; padding-bottom: 0.3em; }}
          code {{ background-color: #f4f4f4; padding: 2px 4px; border-radius: 3px; font-family: monospace; }}
          pre {{ background-color: #f8f9fa; padding: 15px; overflow-x: auto; border-left: 4px solid {title_color}; }}
        </style>
        """

        full_html = f"<!DOCTYPE html><html lang='pt-BR'><head>{css_styles}</head><body>{raw_html}</body></html>"
        return full_html

#!/usr/bin/env python3
import os

class ConfigAuditor:
    name = "config_auditor"
    description = "Verifica a existência de chaves obrigatórias em um arquivo .env."
    input_schema = {
        "type": "object",
        "properties": {
            "file_path": {"type": "string", "description": "Caminho absoluto para o arquivo .env."},
            "required_keys": {"type": "array", "items": {"type": "string"}, "description": "Lista de chaves que devem estar presentes no arquivo."}
        },
        "required": ["file_path", "required_keys"]
    }
    when_to_use = "Quando o usuário solicitar verificação de configuração, auditoria de variáveis de ambiente ou validação de arquivos .env."
    when_not_to_use = "Não use para criar novos arquivos ou modificar valores existentes; apenas leia e valide.

    def execute(self, **kwargs):
        file_path = kwargs.get("file_path")
        required_keys = set(kwargs.get("required_keys", []))

        if not os.path.exists(file_path):
            return f"Erro: O arquivo {file_path} não foi encontrado."

        missing_keys = list(required_keys)
        found_keys = set()

        try:
            with open(file_path, "r", encoding="utf-8") as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith("#"):
                        continue
                    key_part = line.split("=")[0].strip()
                    found_keys.add(key_part)
        except Exception as e:
            return f"Erro ao ler o arquivo: {str(e)}"

        missing_keys = [k for k in required_keys if k not in found_keys]

        status_msg = "Auditoria concluída.\n"
        if missing_keys:
            status_msg += f"Chaves faltando ({len(missing_keys)}): {', '.join(sorted(missing_keys))}\nAção necessária: Adicione as chaves acima ao arquivo .env para evitar falhas na aplicação."
        else:
            status_msg += "Todas as chaves obrigatórias foram encontradas. O ambiente está configurado corretamente conforme a lista solicitada."

        return status_msg

