def analyze_comments(filepath):
    # Leitura e processamento de comentários em Python para análise de sentimento
    result = {}
    with open(filepath) as f:
        content = f.read()
        comments = [line for line in content.split('\n') if '#' in line and not line.strip().startswith('#!')]
        positive, negative, neutral = 0, 0, 0
        keywords_pos = ['excelente', 'bom', 'ótimo']
        keywords_neg = ['ruim', 'erro', 'bug', 'péssimo']
        for c in comments:
            text = c.lower()
            if any(k in text for k in keywords_pos): positive += 1
            elif any(k in text for k in keywords_neg): negative += 1
            else: neutral += 1
    result['total_comments'] = len(comments)
    result['sentiment_distribution'] = {'positive': positive, 'negative': negative, 'neutral': neutral}
    return json.dumps(result)

