class csv_merger:
    name = "csv_merger"
    description = "Mescla múltiplos arquivos CSV baseados em uma coluna chave comum (ID), unindo colunas de diferentes fontes."
    input_schema: Dict[str, Any] = {
        "type": "object",
        "properties": {
            "file_list": {"type": "array", "items": {"type": "string"}, "description": "Lista completa dos caminhos dos arquivos CSV a serem mesclados."},
            "key_column": {"type": "string", "default": "id", "description": "Nome da coluna chave para realizar o join entre os arquivos."}
        },
        "required": ["file_list"]
    }
    when_to_use = "Quando o usuário solicita combinar dados de múltiplos CSVs que compartilham um identificador comum."
    when_not_to_use = "Se os arquivos não possuem colunas compatíveis ou se a operação for apenas leitura simples sem necessidade de junção.",

    def execute(self, **kwargs) -> str:
        try:
            file_list = kwargs.get("file_list")
            key_column = kwargs.get("key_column", "id")

            import csv
            from collections import defaultdict

            merged_data: Dict[str, dict] = {}
            all_columns = set([key_column])

            for filepath in file_list:
                with open(filepath, 'r', newline='', encoding='utf-8') as f:
                    reader = csv.DictReader(f)
                    headers = [h.lower().strip() for h in reader.fieldnames]
                    all_columns.update(headers)
                    key_col_lower = key_column.lower()

                    if not any(h == key_col_lower for h in headers):
                        raise ValueError(f"Coluna chave '{key_column}' não encontrada em {filepath}")

                    current_data_map: Dict[str, dict] = {}
                    for row in reader:
                        normalized_row = {k.lower().strip(): v for k, v in row.items()}
                        key_val = str(normalized_row.get(key_col_lower))
                        if not merged_data or key_val not in merged_data:
                            current_data_map[key_val] = {}
                        # Atualiza ou cria a chave principal
                        if key_val not in merged_data:
                            merged_data[key_val] = {key_column: key_val}

                        for col, val in normalized_row.items():
                            if col != key_col_lower or (col == key_col_lower and col.lower() != str(key_val).lower()): # Evita sobrescrever chave se nome igual
                                merged_data[key_val][col] = val

            # Ordena colunas para consistência
            sorted_columns = sorted(list(all_columns))
            output_path = "resultado_mesclado.csv"
            with open(output_path, 'w', newline='', encoding='utf-8') as f:
                writer = csv.DictWriter(f, fieldnames=sorted_columns)
                writer.writeheader()
                for row in merged_data.values():
                    # Garante que colunas faltantes tenham valor vazio
                    complete_row = {col: row.get(col, "") for col in sorted_columns}
                    writer.writerow(complete_row)

            return f"Sucesso. Arquivos mesclados em '{output_path}' com base na coluna '{key_column}'. Total de registros únicos: {len(merged_data)}."
        except Exception as e:
            return f"Erro ao executar csv_merger: {str(e)}"

