"""
import os

class ToolConfigAuditor:
    name = "config_auditor"
    description = "Verifica se um arquivo .env contém todas as variáveis de ambiente necessárias. Retorna uma lista das chaves faltantes." 
    input_schema = {
        "type": "object",
        "properties": {
            "file_path": {
                "type": "string", 
                "description": "Caminho absoluto ou relativo para o arquivo .env a ser auditado."
            }
        },
        "required": ["file_path"]
    }
    when_to_use = "Quando o usuário precisar validar se um ambiente de configuração está completo antes da implantação." 
    when_not_to_use = "Não usar para criar ou editar arquivos, apenas para leitura e auditoria."

    def execute(self, **kwargs):
        file_path = kwargs.get("file_path")
        required_keys = ["DATABASE_URL", "API_KEY", "DEBUG"]

        if not os.path.exists(file_path):
            return f"Erro: O arquivo {file_path} não foi encontrado."

        found_keys = set()
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith('#'):
                        continue
                    if '=' in line:
                        key = line.split('=', 1)[0].strip()
                        found_keys.add(key)
        except Exception as e:
            return f"Erro ao ler arquivo: {str(e)}"

        missing_keys = [key for key in required_keys if key not in found_keys]
        present_count = len(required_keys) - len(missing_keys)

        result_msg = f"Auditoria concluída em {file_path}.\nChaves obrigatórias: {required_keys}\nEncontradas: {present_count}/{len(required_keys)}"
        if missing_keys:
            result_msg += "\nFaltando:\n- " + "\n- ".join(missing_keys)
        else:
            result_msg += "\nTodas as chaves obrigatórias estão presentes."
        return result_msg

