                    new_key = f"{parent_key}{delimiter}{k}" if parent_key else k
                    if isinstance(v, dict):
                        flatten_obj(v, new_key)
                    elif isinstance(v, list):
                        # Expande listas em índices numéricos ou cria novas linhas se for lista de objetos complexos simplificada aqui
                        items[new_key] = v
                flattened_rows.append(items)

            if isinstance(json_data, dict):
                flatten_obj(json_data)
            elif isinstance(json_data, list) and json_data:
                 # Caso a raiz seja uma lista de dicionários
                 for item in json_data:
                     if isinstance(item, dict): flatten_obj({"root": item})

            return "\n".join([json.dumps(row, ensure_ascii=False) for row in flattened_rows])
        except Exception as e:
            return f"Erro na execução: {str(e)}"

