import os

class TokenCounterTool:
    name = "token_counter"
    description = "Conta o número aproximado de tokens em uma lista de arquivos .txt. Assume ~4 caracteres por token (estimativa padrão)."
    input_schema = {
        "type": "object",
        "properties": {
            "file_paths": {
                "type": "array",
                "items": {"type": "string"},
                "description": "Lista de caminhos absolutos para arquivos .txt."
            }
        },
        "required": ["file_paths"]
    }
    when_to_use = "Quando o usuário solicitar contagem de tokens ou tamanho de conteúdo em arquivos de texto específicos."
    when_not_to_use = "Para arquivos binários, imagens ou quando a precisão exata do tokenizador (ex: tiktoken) não for necessária e uma estimativa rápida bastar."

    def execute(self, **kwargs):
        file_paths = kwargs.get("file_paths", [])
        if not isinstance(file_paths, list):
            return "Erro: O parâmetro 'file_paths' deve ser uma lista de strings."

        total_tokens = 0
        results_log = []
        avg_chars_per_token = 4.0

        for path in file_paths:
            if not os.path.exists(path):
                return f"Erro: Arquivo não encontrado ou inacessível: {path}"
            try:
                with open(path, 'r', encoding='utf-8') as f:
                    content = f.read()
                    char_count = len(content)
                    estimated_tokens = int(char_count / avg_chars_per_token) + (1 if char_count % 4 else 0)
                    total_tokens += estimated_tokens
                    results_log.append(f"{os.path.basename(path)}: {estimated_tokens} tokens")
            except Exception as e:
                return f"Erro ao processar {path}: {str(e)}"

        summary = "\n".join(results_log)
        final_output = f"Resultados detalhados:\n{summary}\nTotal combinado de tokens: {total_tokens}"
        return final_output

