class DiffCheckerTool:
    name = "diff_checker"
    description = "Compara dois diretórios e retorna a lista de arquivos divergentes."
    input_schema: Dict[str, Any] = {
        "type": "object",
        "properties": {
            "dir1": {"type": "string", "description": "Caminho do primeiro diretório."},
            "dir2": {"type": "string", "description": "Caminho do segundo diretório."}
        },
        "required": ["dir1", "dir2"]
    }

    def execute(self, **kwargs) -> str:
        dir1 = kwargs.get("dir1")
        dir2 = kwargs.get("dir2")

        try:
            files1 = set(os.listdir(dir1)) if os.path.exists(dir1) else set()
            files2 = set(os.listdir(dir2)) if os.path.exists(dir2) else set()

            only_in_1 = list(files1 - files2)
            only_in_2 = list(files2 - files1)
            common = files1 & files2
            divergent_common = []

            for f in sorted(common):
                p1, p2 = os.path.join(dir1, f), os.path.join(dir2, f)
                if not (os.path.isfile(p1) and os.path.isfile(p2)):
                    continue
                with open(p1, 'r', encoding='utf-8') as fp1, open(p2, 'r', encoding='utf-8') as fp2:
                    if fp1.read() != fp2.read():
                        divergent_common.append(f)

            result = "Arquivos apenas em dir1: {}\nArquivos apenas em dir2: {}\nArquivos comuns com conteúdo diferente: {}".format(only_in_1, only_in_2, divergent_common)
        except Exception as e:
            result = f"Erro ao comparar diretórios: {str(e)}"
        return result

