import json
from typing import Dict, Any

class ConfigAuditorTool:
    name = "config_auditor"
    description = "Analisa arquivos de configuração e detecta chaves ausentes."
    input_schema: Dict[str, Any] = {
        "type": "object",
        "properties": {
            "expected_keys": {"type": "array", "items": {"type": "string"}},
            "env_file_path": {"type": "string"}
        },
        "required": ["expected_keys"]
    }

    def execute(self, **kwargs) -> str:
        expected = set(kwargs.get("expected_keys", []))
        found = set()
        try:
            with open(".env") as f:
                for line in f:
                    if "=" in line and not line.strip().startswith("#"):
                        key = line.split("=")[0].strip()
                        found.add(key)
        except FileNotFoundError:
            return json.dumps({"status": "error", "message": "Arquivo .env não encontrado."})

        missing = expected - found
        result = {
            "expected_keys": list(expected),
            "found_keys": sorted(list(found)),
            "missing_keys": sorted(list(missing)) if missing else []
        }
        return json.dumps(result, ensure_ascii=False)

